import { products, categories, money, escapeHTML as esc, defaultVariant } from './data.js';
import { productCard, promises, buttonLink, icon, breadcrumb, stars, cartLines, summary, emptyCart } from './components.js';

export function homePage() {
  return `<section class="hero"><img class="hero-image" src="assets/hero.png" alt="Sunlit industrial home gym with a black power rack, bench and strength equipment" width="1672" height="941" fetchpriority="high"><div class="hero-content"><div class="eyebrow hero-eyebrow"><span></span> STRONGER STARTS HERE</div><h1>BUILT FOR<br>YOUR NEXT<br><em>LEVEL.</em></h1><p>Serious equipment. Everyday progress.<br>Build a gym that’s built around you.</p><div class="hero-buttons">${buttonLink('#/shop', 'Shop equipment')}<a href="#/about" class="hero-story">Meet OMIGYM <span>↗</span></a></div><div class="hero-footnote"><span class="hero-rule"></span> FOR THE FIRST REP. AND EVERY REP AFTER.</div></div><div class="hero-caption"><span>THE OMIGYM STANDARD</span><strong>NO SHORTCUTS.<br>JUST STRENGTH.</strong><span>01 — HOME GYM SERIES</span></div></section>${promises()}<section class="section category-section"><div class="section-heading"><div><span class="eyebrow">YOUR GOALS. YOUR GEAR.</span><h2>FIND YOUR STRENGTH.</h2></div><a class="text-link" href="#/shop">Shop all equipment <span>↗</span></a></div><div class="category-grid">${[{name:'Dumbbells', image:'dumbbells.png', detail:'Make every rep count', number:'01'}, {name:'Racks & benches',image:'rack.png',detail:'Build your foundation',number:'02'}, {name:'Weight plates',image:'plates.png',detail:'Add to your potential',number:'03'}, {name:'Gym packages',image:'bench.png',detail:'Bring it all together',number:'04'}].map(c => `<a class="category-card" href="#/shop?category=${encodeURIComponent(c.name)}"><span class="category-number">${c.number} /</span><img src="assets/${c.image}" alt="" width="400" height="400" loading="lazy"><div><h3>${c.name}</h3><span>${c.detail}</span></div><span class="category-arrow">↗</span></a>`).join('')}</div></section><section class="section bestsellers"><div class="section-heading"><div><span class="eyebrow">THE HEAVY ROTATION</span><h2>PROVEN FAVORITES.</h2></div><a class="text-link" href="#/shop">View all products <span>↗</span></a></div><div class="product-grid">${products.slice(0, 4).map(productCard).join('')}</div></section><section class="brand-story"><div class="story-photo"><img src="assets/original-7-5.png" alt="Close-up of original OMIGYM dumbbells with orange brand markings" width="1694" height="1056" loading="lazy"><span>DETAILS THAT MAKE THE DIFFERENCE.</span></div><div class="story-copy"><span class="eyebrow">NOT JUST EQUIPMENT. A MINDSET.</span><h2>YOUR SPACE.<br>YOUR PACE.<br><em>YOUR STRONG.</em></h2><p>Progress doesn’t need a crowded gym. It needs a little space, a lot of commitment, and equipment that shows up with you.</p><p>We build the essentials. You build the rest.</p>${buttonLink('#/about', 'The OMIGYM story', 'dark')}</div></section><section class="closing-banner"><div><span class="eyebrow">SMALL SPACE. BIG AMBITIONS.</span><h2>MAKE ROOM FOR STRONGER.</h2></div>${buttonLink('#/shop?category=Gym%20packages', 'Build your home gym', 'light')}</section>`;
}

export function shopPage(params = new URLSearchParams()) {
  const category = categories.includes(params.get('category')) ? params.get('category') : 'All equipment';
  const query = params.get('search') || '';
  return `<div class="page-wrap">${breadcrumb([['Equipment']])}<section class="catalog-intro"><div><span class="eyebrow">GOOD EQUIPMENT. REAL PROGRESS.</span><h1>GEAR UP.<br><em>GO FURTHER.</em></h1></div><p>From your first pair of dumbbells to your full home setup.<br>Find the equipment that meets you where you are.</p></section><div class="catalog-toolbar"><div class="filter-tabs" role="group" aria-label="Equipment categories">${categories.map(c => `<button data-action="category" data-category="${esc(c)}" class="filter-tab ${category === c ? 'active' : ''}" aria-pressed="${category === c}">${c}</button>`).join('')}</div><div class="catalog-controls"><label class="search-field"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input type="search" id="catalog-search" placeholder="Find your equipment" aria-label="Search products" value="${esc(query)}" maxlength="100"></label><label class="sort-label">Sort by <select id="catalog-sort" aria-label="Sort products"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="name">Name: A–Z</option></select></label></div></div><div class="result-info"><span id="result-count" role="status"></span><span>Built for the way you train.</span></div><div class="product-grid catalog-grid" id="catalog-results" data-category="${esc(category)}"></div><div class="catalog-help"><div>${icon('strength')}<span><strong>A little help building your gym?</strong><p>Tell us about your space. We’ll help you find a starting point.</p></span></div><a class="text-link" href="#/contact">Let’s talk <span>↗</span></a></div></div>`;
}

export function productPage(p) {
  const selected = defaultVariant(p);
  return `<div class="page-wrap product-page">${breadcrumb([['Equipment', '#/shop'], [p.category, '#/shop?category=' + encodeURIComponent(p.category)], [p.name]])}<section class="product-detail"><div class="product-gallery"><div class="main-product-image">${p.tag ? `<span class="product-badge">${p.tag}</span>` : ''}<img id="detail-image" src="assets/${p.image}" alt="${esc(p.name)} — studio view" width="800" height="800"></div><div class="gallery-thumbs" aria-label="Product images">${p.images.map((image, index) => `<button class="gallery-thumb ${index === 0 ? 'selected' : ''}" data-action="gallery" data-image="${image}" data-caption="${esc(p.name)} — ${index === 0 ? 'studio view' : 'detail view ' + index}" aria-label="View product image ${index + 1}" aria-pressed="${index === 0}"><img src="assets/${image}" alt="" width="90" height="90"></button>`).join('')}</div><p class="image-note">${p.id === 'dumbbell-set' || p.id === 'starter-package' ? 'Package contents are listed in the specifications. Images show individual components.' : 'Images are illustrative. See specifications for the selected configuration.'}</p></div><div class="product-info"><span class="eyebrow">OMIGYM / ${p.category.toUpperCase()}</span><h1>${p.name.toUpperCase()}</h1><div class="detail-rating">${stars(p.rating, p.reviews)}</div><div class="detail-price"><strong id="detail-price">${money(p.price)}</strong><del id="detail-compare">${p.compare ? money(p.compare) : ''}</del><span class="in-stock">${icon('check')} In stock</span></div><p class="product-subtitle">${p.subtitle}</p><p class="description">${p.description}</p><form id="product-form" data-id="${p.id}"><fieldset class="variant-fieldset"><legend>${p.optionLabel || (p.category === 'Dumbbells' || p.category === 'Weight plates' ? 'SELECT WEIGHT' : 'CONFIGURATION')}</legend><div class="variant-options">${p.variants.map(v => `<label class="variant"><input type="radio" name="variant" value="${esc(v.name)}" data-price="${v.price}" ${v.name === selected ? 'checked' : ''}><span>${esc(v.name)}</span></label>`).join('')}</div></fieldset><label class="quantity-label" for="product-quantity">QUANTITY</label><div class="buy-row"><div class="quantity"><button type="button" data-action="product-quantity" data-delta="-1" aria-label="Decrease quantity">−</button><input type="number" id="product-quantity" name="quantity" value="1" min="1" max="20" step="1" aria-label="Product quantity" required><button type="button" data-action="product-quantity" data-delta="1" aria-label="Increase quantity">+</button></div><button class="button full" type="submit">Add to bag ${icon('bag')}</button></div></form><div class="product-delivery"><span>${icon('truck')} $7 flat-rate shipping</span><span>${icon('return')} 30-day returns</span></div><div class="product-accordions"><details open><summary>WHY YOU’LL LOVE IT</summary><ul>${p.features.map(f => `<li>${icon('check')}${f}</li>`).join('')}</ul></details><details><summary>SPECIFICATIONS</summary><dl class="spec-list">${p.specs.map(([key, value]) => `<div><dt>${key}</dt><dd>${value}</dd></div>`).join('')}</dl></details><details><summary>SHIPPING & RETURNS</summary><p>Standard shipping is a flat $7 per order. Estimated delivery: 5–7 business days. Unused equipment may be returned within 30 days.</p><a href="#/contact?topic=Shipping%20%26%20delivery" class="text-link">Ask us a question <span>↗</span></a></details></div></div></section><section class="related-section"><div class="section-heading"><div><span class="eyebrow">BETTER TOGETHER</span><h2>ROUND OUT YOUR SETUP.</h2></div><a href="#/shop" class="text-link">Explore all <span>↗</span></a></div><div class="product-grid">${products.filter(item => item.id !== p.id).slice(0,4).map(productCard).join('')}</div></section></div>`;
}

export function cartPage(cart) {
  return `<div class="page-wrap">${breadcrumb([['Shopping bag']])}<div class="page-heading"><span class="eyebrow">ONE STEP CLOSER TO STRONGER</span><h1>YOUR BAG.</h1></div>${cart.length ? `<div class="checkout-layout"><section class="cart-items" aria-label="Bag items">${cartLines(cart)}<a href="#/shop" class="text-link continue-link">← Continue shopping</a></section>${summary(cart)}</div>` : emptyCart()}</div>`;
}

export function checkoutPage(cart) {
  if (!cart.length) return `<div class="page-wrap">${breadcrumb([['Checkout']])}<div class="page-heading"><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h1>CHECKOUT.</h1></div>${emptyCart()}</div>`;
  return `<div class="page-wrap">${breadcrumb([['Shopping bag', '#/cart'], ['Checkout']])}<div class="page-heading"><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h1>MAKE IT YOURS.</h1><p>Complete your delivery details to place your order.</p></div><div class="checkout-steps"><a href="#/cart">01 &nbsp; Your bag</a><span class="active">02 &nbsp; Delivery details</span><span>03 &nbsp; Confirmation</span></div><div class="checkout-layout"><form id="checkout-form" class="checkout-form"><div class="form-section"><h2>CONTACT DETAILS</h2><label>Email address <input name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="120"></label></div><div class="form-section"><h2>DELIVERY ADDRESS</h2><div class="field-row"><label>First name <input name="firstName" autocomplete="given-name" required maxlength="50"></label><label>Last name <input name="lastName" autocomplete="family-name" required maxlength="50"></label></div><label>Street address <input name="address" autocomplete="address-line1" placeholder="House number and street" required maxlength="160"></label><label>Apartment, suite, etc. <span class="optional">(optional)</span><input name="apartment" autocomplete="address-line2" maxlength="100"></label><div class="field-row"><label>City <input name="city" autocomplete="address-level2" required maxlength="80"></label><label>State / region <input name="region" autocomplete="address-level1" required maxlength="80"></label></div><div class="field-row"><label>ZIP / postal code <input name="postal" autocomplete="postal-code" required maxlength="16"></label><label>Country <select name="country" autocomplete="country-name" required><option>United States</option><option>Canada</option><option>United Kingdom</option><option>Australia</option><option>Singapore</option><option>China</option><option>Other</option></select></label></div><label>Phone number <span class="optional">(optional)</span><input name="phone" type="tel" autocomplete="tel" maxlength="30"></label></div><div class="form-section"><h2>DELIVERY METHOD</h2><div class="shipping-method"><span class="radio-dot"></span><span><strong>Standard delivery</strong><small>Estimated delivery: 5–7 business days</small></span><strong id="shipping-cost"></strong></div></div><label class="consent"><input type="checkbox" name="deliveryConsent" required><span>I confirm that my delivery details are correct.</span></label><p class="form-error" id="checkout-error" role="alert"></p><button class="button full" type="submit">Place order ${icon('arrow')}</button></form><aside class="checkout-summary"><div class="checkout-preview">${cartLines(cart, true)}</div>${summary(cart, false)}</aside></div></div>`;
}

export function confirmationPage(order) {
  if (!order) return `<div class="page-wrap"><div class="empty-state">${icon('bag')}<h1>NO ORDER HERE YET.</h1><p>Find your next training essential to get started.</p>${buttonLink('#/shop', 'Shop equipment')}</div></div>`;
  return `<div class="page-wrap confirmation"><div class="success-icon">${icon('check')}</div><span class="eyebrow">A STRONG START.</span><h1>YOU’RE ALL SET.</h1><p>Your order has been placed.<br>Now imagine your next great workout.</p><div class="order-reference"><span>ORDER REFERENCE</span><strong>${esc(order.id)}</strong><span>${new Date(order.date).toLocaleDateString('en-US', {year:'numeric',month:'long',day:'numeric'})}</span></div><div class="confirmation-card"><h2>YOUR EQUIPMENT</h2>${cartLines(order.items, true)}<div class="summary-row"><span>Subtotal</span><span>${money(order.subtotal)}</span></div><div class="summary-row"><span>Standard shipping</span><span>${money(order.shipping)}</span></div><div class="summary-total"><span>Order total</span><strong>${money(order.total)}</strong></div></div>${buttonLink('#/shop', 'Keep exploring')}<a href="#/" class="back-home">Back to home</a></div>`;
}

export function aboutPage() {
  return `<section class="about-hero"><img src="assets/hero.png" alt="OMIGYM vision: a dedicated home training space" width="1672" height="941"><div><span class="eyebrow">THIS IS OMIGYM.</span><h1>STRENGTH IS<br><em>PERSONAL.</em></h1><p>Your goals. Your routine. Your place to become more.</p></div></section><section class="section about-intro"><span class="eyebrow">OUR REASON TO SHOW UP</span><div><h2>LESS BETWEEN YOU<br>AND YOUR NEXT REP.</h2><p>We believe the best gym is the one you actually use. The corner of your garage. The spare room. The space you make your own.</p><p>OMIGYM is built around a simple idea: dependable equipment should make it easier to show up. No noise. No unnecessary complications. Just thoughtfully designed essentials that feel right, work hard, and belong in your everyday life.</p><p>Whether you’re picking up your first dumbbell or building out your dream setup, there’s a place for you here.</p></div></section><section class="brand-story about-craft"><div class="story-photo"><img src="assets/original-5.png" alt="Original 5 kg OMIGYM dumbbells, showing textured rubber and chrome handles" width="1702" height="1120" loading="lazy"></div><div class="story-copy"><span class="eyebrow">PURPOSE IN EVERY DETAIL</span><h2>FEEL THE<br><em>DIFFERENCE.</em></h2><p>The texture of a grip. The balance of a dumbbell. The reassuring stability of a bench. The small details add up to equipment you look forward to using.</p><p>That’s our standard. From the first warm-up to the last set.</p></div></section><section class="section values"><article><span>01 /</span><h2>BUILT WITH INTENTION.</h2><p>Practical design. Durable materials. Equipment that does its job, so you can focus on yours.</p></article><article><span>02 /</span><h2>MADE FOR REAL LIFE.</h2><p>Training should fit your space and your schedule. Start small. Make it consistent. Grow from there.</p></article><article><span>03 /</span><h2>PROGRESS IS YOURS.</h2><p>No perfect starting point required. We’re here for your first rep and every rep after it.</p></article></section><section class="closing-banner"><div><span class="eyebrow">LET’S GET TO WORK.</span><h2>YOUR NEXT LEVEL IS WAITING.</h2></div>${buttonLink('#/shop', 'Find your equipment', 'light')}</section>`;
}

export function contactPage(params = new URLSearchParams()) {
  const topics = ['Product advice', 'Shipping & delivery', 'Returns & warranty', 'Something else'];
  return `<div class="page-wrap">${breadcrumb([['Contact']])}<section class="contact-layout"><div class="contact-intro"><span class="eyebrow">REAL QUESTIONS. A LITTLE GUIDANCE.</span><h1>LET’S TALK<br><em>STRONG.</em></h1><p>Choosing your first setup? Making more of your space?<br>We’re here to help you find your next step.</p><div class="contact-method">${icon('mail')}<div><h3>Drop us a line</h3><span>hello@omigym.com</span><small>Monday–Friday, 9am–6pm (ET)</small></div></div><div class="contact-method">${icon('pin')}<div><h3>Our training ground</h3><span>128 Strength Avenue, Austin, TX 78701</span><small>+1 (512) 555-0186</small></div></div></div><div class="contact-form-panel"><h2>HOW CAN WE HELP?</h2><p>A little detail goes a long way.</p><form id="contact-form"><div class="field-row"><label>Your name <input name="name" autocomplete="name" placeholder="Alex Morgan" required maxlength="100"></label><label>Email address <input type="email" name="email" autocomplete="email" placeholder="you@example.com" required maxlength="120"></label></div><label>What’s on your mind? <select name="topic">${topics.map(t => `<option ${params.get('topic') === t ? 'selected' : ''}>${t}</option>`).join('')}</select></label><label>Your message <textarea name="message" rows="5" placeholder="Tell us a little about your space, goals, or question…" required minlength="10" maxlength="2000"></textarea></label><button type="submit" class="button full">Send message ${icon('arrow')}</button></form><div class="contact-success" id="contact-success" role="status" hidden></div></div></section><section class="faq-section"><div><span class="eyebrow">A FEW QUICK ANSWERS</span><h2>GOOD TO KNOW.</h2></div><div class="faq-list"><details><summary>Where should I start with my home gym?</summary><p>A pair of dumbbells and an adjustable bench make a versatile starting point. Add plates and a rack as your space and training needs grow. Explore our Gym Packages for ready-to-go combinations.</p></details><details><summary>How does shipping work?</summary><p>Standard shipping is a flat $7 per order, with an estimated delivery time of 5–7 business days.</p></details><details><summary>Can I return my equipment?</summary><p>Unused equipment in its original packaging may be returned within 30 days. Contact our team with your order reference for help with a return.</p></details><details><summary>Where can I find my order reference?</summary><p>Your order reference appears on the confirmation page after checkout. Keep it handy when contacting us about your equipment.</p></details></div></section></div>`;
}

export const notFoundPage = () => `<div class="page-wrap"><div class="empty-state"><span class="eyebrow">404 / A LITTLE OFF TRACK</span><h1>LET’S GET YOU<br>BACK TO TRAINING.</h1><p>We couldn’t find that page or product.</p>${buttonLink('#/shop', 'Explore equipment')}</div></div>`;
